-- ReWear initial schema.
-- Mirrors the frontend types in src/lib/store.ts (User, StoredItem, Exchange, AppNotification, wishlist).
-- Kept to SQL that both PostgreSQL and H2 (PostgreSQL mode, used in tests) accept:
-- UUIDs are generated by the application, VARCHAR instead of TEXT, no PostgreSQL-only functions.

CREATE TABLE users (
    id             UUID                     PRIMARY KEY,
    name           VARCHAR(100)             NOT NULL,
    email          VARCHAR(255)             NOT NULL,
    password_hash  VARCHAR(100)             NOT NULL,
    initials       VARCHAR(4)               NOT NULL,
    avatar_color   VARCHAR(7)               NOT NULL,
    location       VARCHAR(100)             NOT NULL DEFAULT '',
    bio            VARCHAR(500)             NOT NULL DEFAULT '',
    eco_points     INTEGER                  NOT NULL DEFAULT 0,
    co2_saved      DOUBLE PRECISION         NOT NULL DEFAULT 0,
    textile_saved  DOUBLE PRECISION         NOT NULL DEFAULT 0,
    exchange_count INTEGER                  NOT NULL DEFAULT 0,
    donation_count INTEGER                  NOT NULL DEFAULT 0,
    created_at     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_users_email UNIQUE (email)
);

-- User.badges: string[]
CREATE TABLE user_badges (
    user_id    UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    sort_order INTEGER     NOT NULL,
    badge      VARCHAR(50) NOT NULL,
    PRIMARY KEY (user_id, sort_order)
);

-- User.stylePreferences: string[]
CREATE TABLE user_style_preferences (
    user_id    UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    sort_order INTEGER     NOT NULL,
    preference VARCHAR(50) NOT NULL,
    PRIMARY KEY (user_id, sort_order)
);

CREATE TABLE items (
    id                   UUID                     PRIMARY KEY,
    owner_id             UUID                     NOT NULL REFERENCES users (id),
    title                VARCHAR(120)             NOT NULL,
    brand                VARCHAR(80)              NOT NULL,
    category             VARCHAR(50)              NOT NULL,
    item_condition       VARCHAR(20)              NOT NULL,
    size                 VARCHAR(20)              NOT NULL,
    gender               VARCHAR(10)              NOT NULL,
    location             VARCHAR(100)             NOT NULL,
    sustainability_score INTEGER                  NOT NULL,
    image_url            VARCHAR(500)             NOT NULL,
    description          VARCHAR(2000)            NOT NULL,
    point_value          INTEGER                  NOT NULL,
    listed_at            TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    exchange_count       INTEGER                  NOT NULL DEFAULT 0,
    is_available         BOOLEAN                  NOT NULL DEFAULT TRUE,
    CONSTRAINT ck_items_condition CHECK (item_condition IN ('Like New', 'Excellent', 'Good', 'Fair')),
    CONSTRAINT ck_items_gender CHECK (gender IN ('Women', 'Men', 'Unisex')),
    CONSTRAINT ck_items_score CHECK (sustainability_score BETWEEN 0 AND 100),
    CONSTRAINT ck_items_points CHECK (point_value >= 0)
);

CREATE INDEX idx_items_category ON items (category);
CREATE INDEX idx_items_owner_id ON items (owner_id);

-- StoredItem.images: string[] (ordered)
CREATE TABLE item_images (
    item_id    UUID         NOT NULL REFERENCES items (id) ON DELETE CASCADE,
    sort_order INTEGER      NOT NULL,
    image_url  VARCHAR(500) NOT NULL,
    PRIMARY KEY (item_id, sort_order)
);

CREATE TABLE wishlist_entries (
    id         UUID                     PRIMARY KEY,
    user_id    UUID                     NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    item_id    UUID                     NOT NULL REFERENCES items (id) ON DELETE CASCADE,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_wishlist_user_item UNIQUE (user_id, item_id)
);

CREATE TABLE exchanges (
    id               UUID                     PRIMARY KEY,
    item_id          UUID                     NOT NULL REFERENCES items (id),
    requester_id     UUID                     NOT NULL REFERENCES users (id),
    owner_id         UUID                     NOT NULL REFERENCES users (id),
    proposed_item_id UUID                     REFERENCES items (id) ON DELETE SET NULL,
    message          VARCHAR(1000)            NOT NULL,
    status           VARCHAR(10)              NOT NULL DEFAULT 'pending',
    exchange_type    VARCHAR(10)              NOT NULL,
    created_at       TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_exchanges_status CHECK (status IN ('pending', 'accepted', 'declined')),
    CONSTRAINT ck_exchanges_type CHECK (exchange_type IN ('exchange', 'donate')),
    CONSTRAINT ck_exchanges_not_self CHECK (requester_id <> owner_id)
);

CREATE INDEX idx_exchanges_owner_id ON exchanges (owner_id);
CREATE INDEX idx_exchanges_requester_id ON exchanges (requester_id);

CREATE TABLE notifications (
    id                UUID                     PRIMARY KEY,
    user_id           UUID                     NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    message           VARCHAR(500)             NOT NULL,
    link              VARCHAR(255),
    is_read           BOOLEAN                  NOT NULL DEFAULT FALSE,
    notification_type VARCHAR(10)              NOT NULL,
    created_at        TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_notifications_type CHECK (notification_type IN ('exchange', 'badge', 'wishlist', 'system', 'donate'))
);

CREATE INDEX idx_notifications_user_read ON notifications (user_id, is_read);
